        if not m: return []
        key,op,rhs=m.groups()
        try: rhs=json.loads(rhs)
        except: rhs=rhs.strip("'\"")
        found=[]
        def rec(n):
            if isinstance(n,dict):
                if key in n and ((n[key]==rhs) == (op=='==')): found.append(n)
                for x in n.values(): rec(x)
            elif isinstance(n,list):
                for x in n: rec(x)
        rec(data); return found
    if q.startswith('"') and q.endswith('"'): return json.loads(q)
    if q.startswith("'") and q.endswith("'"): return q[1:-1]
    if q in ('true','false','null') or re.fullmatch(r'-?\d+(\.\d+)?',q):
