            else: msg='execution error when processing ast.CallExpr: '+msg
            msg='error executing selector: '+msg
        else: msg='error: '+msg
        sys.stderr.write('dasel: error: '+msg+'\n'); return 1

def parse_simple_yaml(s):
    # Lightweight indentation-based mappings, sufficient for common documents.
    lines=[(len(x)-len(x.lstrip()),x.strip()) for x in s.splitlines() if x.strip() and not x.lstrip().startswith('#')]
    if not lines: return None
    root={}; stack=[(-1,root)]
    def scalar(x):
        if x in ('true','True'): return True
        if x in ('false','False'): return False
        if x in ('null','~'): return None
        try: return json.loads(x)
        except: return x.strip("'\"")
    for ind,line in lines:
        if ':' not in line: continue
        k,v=line.split(':',1); k=k.strip().strip("'\""); v=v.strip()
